fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    // Determine a split point: floor(length/2).
    // This guarantees that when length > 1, both parts are strictly shorter than the original.
    let mut first = a;
    let mid = first.len() / 2;
    // `Vec::split_off` takes all elements from `mid..` out of `first` and returns them as a new Vec.
    let second = first.split_off(mid);
    (first, second)
}

